package rich

import (
	"compress/gzip"
	"encoding/json"
	"io"
	"os"
	"strings"
	"testing"
)

// PYF-14: console.print on a colour terminal (markup + ReprHighlighter) for
// rich's three colour systems. testdata/color.json.gz is generated by
// testdata/colgen.py from the oracle's rich (Console(force_terminal=True,
// color_system=..., width=80)).
func TestColorCorpus(t *testing.T) {
	t.Setenv("NO_COLOR", "")
	var r io.Reader
	if p := os.Getenv("RICH_COLOR_CORPUS"); p != "" {
		f, err := os.Open(p)
		if err != nil {
			t.Fatal(err)
		}
		defer f.Close()
		r = f
	} else {
		f, err := os.Open("testdata/color.json.gz")
		if err != nil {
			t.Fatal(err)
		}
		defer f.Close()
		gz, err := gzip.NewReader(f)
		if err != nil {
			t.Fatal(err)
		}
		r = gz
	}
	var cases []struct {
		Src string            `json:"src"`
		Out map[string]string `json:"out"`
	}
	if err := json.NewDecoder(r).Decode(&cases); err != nil {
		t.Fatal(err)
	}
	systems := map[string]ColorSystem{"standard": Standard, "256": EightBit, "truecolor": TrueColor}
	fails := 0
	for i, c := range cases {
		for name, want := range c.Out {
			if strings.HasPrefix(want, "ERR ") {
				continue
			}
			var b strings.Builder
			if !printColor(&b, c.Src, 80, systems[name]) {
				t.Errorf("case %d %s: markup error for %q", i, name, c.Src)
				fails++
				continue
			}
			if got := b.String(); got != want {
				t.Errorf("case %d %s: %q\nwant %q\ngot  %q", i, name, c.Src, want, got)
				fails++
			}
		}
		if fails > 20 {
			t.Fatal("too many failures")
		}
	}
}
